    WHEN 'BOTTE-036' THEN 'common'::public.lottery_card_rarity
    WHEN 'BOTTE-037' THEN 'common'::public.lottery_card_rarity
    WHEN 'BOTTE-038' THEN 'common'::public.lottery_card_rarity
    WHEN 'BOTTE-039' THEN 'epic'::public.lottery_card_rarity
