DO $$ BEGIN
  IF (SELECT count(*) FROM public.lottery_card_collections WHERE code='BOTTE_DU_CHANVRIER_2026') <> 1
    OR (SELECT count(*) FROM public.lottery_card_definitions d JOIN kq_botte_v3_catalog c USING(code) WHERE c.card_number <= 36) <> 24
    OR (SELECT count(*) FROM public.lottery_card_definitions WHERE code IN ('BOTTE-002', 'BOTTE-004', 'BOTTE-010', 'BOTTE-011', 'BOTTE-012', 'BOTTE-022', 'BOTTE-023', 'BOTTE-025')) <> 8
  THEN RAISE EXCEPTION 'kq_botte_catalog_incomplete'; END IF;
END $$;

ALTER TABLE public.kq_support_card_rules ADD COLUMN IF NOT EXISTS situation_codes TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE public.kq_support_card_rules DROP CONSTRAINT IF EXISTS kq_support_card_rules_effect_check;
ALTER TABLE public.kq_support_card_rules ADD CONSTRAINT kq_support_card_rules_effect_check
  CHECK(effect IN ('aeroponic-precision', 'bill-relief', 'biochar-buffer', 'cancel-danger', 'clean-cut', 'compliance-clearance', 'compost-buffer', 'controlled-drying', 'cross-diagnosis', 'danger-to-neutral', 'double-danger-shield', 'emergency-adjustment', 'expert-recovery', 'four-keep-three', 'gentle-recovery', 'harvest-cool', 'harvest-four-quality', 'harvest-team', 'humidity-balance', 'hydroponic-control', 'hygiene-buffer', 'hygrometer-balance', 'illegal-power', 'leaf-thinning', 'living-soil-buffer', 'moisture-calibration', 'neutral-to-success', 'organic-feed', 'patient-curing', 'pbi-mite-shield', 'pbi-neutral-strong', 'pbi-strong-success', 'pbi-success', 'pbi-success-xp', 'pbi-thrips-relief', 'perlite-drainage', 'pest-monitor', 'reroll-neutral', 'reroll-two-low', 'reveal-pest', 'root-aeration', 'safe-neutral-reroll', 'shade-screen', 'starter-stability', 'theft-guard', 'thermal-check', 'three-to-success', 'timer-reset', 'water-rescue', 'water-test'));

UPDATE public.lottery_card_definitions SET is_active=false,updated_at=now()
WHERE code IN ('BOTTE-002', 'BOTTE-004', 'BOTTE-010', 'BOTTE-011', 'BOTTE-012', 'BOTTE-022', 'BOTTE-023', 'BOTTE-025');

INSERT INTO public.lottery_card_definitions(collection_id,code,card_number,name,rarity,description,visual_prompt,image_url,is_active)
SELECT collection.id,card.code,card.card_number,card.name,card.rarity,card.description,'',card.image_url,true
FROM kq_botte_v3_catalog card CROSS JOIN public.lottery_card_collections collection
WHERE collection.code='BOTTE_DU_CHANVRIER_2026'
ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,rarity=EXCLUDED.rarity,description=EXCLUDED.description,
  image_url=EXCLUDED.image_url,is_active=true,updated_at=now();

INSERT INTO public.kq_support_card_rules(card_definition_id,category,timing,effect,xp_cost,tags,targets,situation_codes,advantage,drawback,rules_version)
SELECT definition.id,card.category,card.timing,card.effect,card.xp_cost,card.tags,card.targets,card.situation_codes,card.advantage,card.drawback,1
FROM kq_botte_v3_catalog card JOIN public.lottery_card_definitions definition USING(code)
ON CONFLICT(card_definition_id) DO UPDATE SET category=EXCLUDED.category,timing=EXCLUDED.timing,effect=EXCLUDED.effect,
  xp_cost=EXCLUDED.xp_cost,tags=EXCLUDED.tags,targets=EXCLUDED.targets,situation_codes=EXCLUDED.situation_codes,
  advantage=EXCLUDED.advantage,drawback=EXCLUDED.drawback,
  rules_version=public.kq_support_card_rules.rules_version+1,updated_at=now();

-- The generic lottery editor also writes this table; protect every write path.
CREATE OR REPLACE FUNCTION public.kq_guard_botte_official_rarity()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE official_rarity public.lottery_card_rarity;
BEGIN
  official_rarity:=public.kq_botte_official_rarity(NEW.code);
  IF official_rarity IS NOT NULL AND NEW.rarity IS DISTINCT FROM official_rarity
    THEN RAISE EXCEPTION 'kq_botte_rarity_locked'; END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.kq_guard_botte_official_rarity() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS kq_botte_official_rarity_guard ON public.lottery_card_definitions;
CREATE TRIGGER kq_botte_official_rarity_guard BEFORE INSERT OR UPDATE OF rarity,code
  ON public.lottery_card_definitions FOR EACH ROW EXECUTE FUNCTION public.kq_guard_botte_official_rarity();

-- Private shared draw prevents bot victories from bypassing rarity odds.
CREATE OR REPLACE FUNCTION public.kq_pick_support_card(p_guarantee_common BOOLEAN DEFAULT false)
RETURNS public.lottery_card_definitions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_collection_id UUID; v_rarity public.lottery_card_rarity; v_roll INTEGER;
  v_count INTEGER; v_offset INTEGER; v_card public.lottery_card_definitions%ROWTYPE;
BEGIN
  SELECT id INTO v_collection_id FROM public.lottery_card_collections
    WHERE code='BOTTE_DU_CHANVRIER_2026' AND is_active=true;
  IF NOT FOUND THEN RAISE EXCEPTION 'kq_support_collection_unavailable'; END IF;
  IF p_guarantee_common IS TRUE THEN v_rarity:='common';
  ELSE
    v_roll:=public.lottery_secure_random_int(1,100);
    v_rarity:=CASE WHEN v_roll<=70 THEN 'common'::public.lottery_card_rarity
      WHEN v_roll<=93 THEN 'silver'::public.lottery_card_rarity
      WHEN v_roll<=99 THEN 'gold'::public.lottery_card_rarity ELSE 'epic'::public.lottery_card_rarity END;
  END IF;
  SELECT count(*) INTO v_count FROM public.lottery_card_definitions
    WHERE collection_id=v_collection_id AND rarity=v_rarity AND is_active=true AND code IN ('BOTTE-003', 'BOTTE-005', 'BOTTE-006', 'BOTTE-013', 'BOTTE-014', 'BOTTE-015', 'BOTTE-016', 'BOTTE-017', 'BOTTE-018', 'BOTTE-019', 'BOTTE-020', 'BOTTE-021', 'BOTTE-024', 'BOTTE-026', 'BOTTE-027', 'BOTTE-028', 'BOTTE-029', 'BOTTE-030', 'BOTTE-031', 'BOTTE-032', 'BOTTE-033', 'BOTTE-034', 'BOTTE-035', 'BOTTE-036', 'BOTTE-037', 'BOTTE-038', 'BOTTE-039', 'BOTTE-040', 'BOTTE-041', 'BOTTE-042');
  IF v_count=0 THEN RAISE EXCEPTION 'kq_support_rarity_unavailable'; END IF;
  v_offset:=public.lottery_secure_random_int(0,v_count-1);
  SELECT * INTO v_card FROM public.lottery_card_definitions
    WHERE collection_id=v_collection_id AND rarity=v_rarity AND is_active=true AND code IN ('BOTTE-003', 'BOTTE-005', 'BOTTE-006', 'BOTTE-013', 'BOTTE-014', 'BOTTE-015', 'BOTTE-016', 'BOTTE-017', 'BOTTE-018', 'BOTTE-019', 'BOTTE-020', 'BOTTE-021', 'BOTTE-024', 'BOTTE-026', 'BOTTE-027', 'BOTTE-028', 'BOTTE-029', 'BOTTE-030', 'BOTTE-031', 'BOTTE-032', 'BOTTE-033', 'BOTTE-034', 'BOTTE-035', 'BOTTE-036', 'BOTTE-037', 'BOTTE-038', 'BOTTE-039', 'BOTTE-040', 'BOTTE-041', 'BOTTE-042')
    ORDER BY card_number OFFSET v_offset LIMIT 1;
  RETURN v_card;
END $$;
REVOKE ALL ON FUNCTION public.kq_pick_support_card(BOOLEAN) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.rpc_kq_open_support_booster(p_entitlement_id UUID, p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_entitlement public.kq_support_booster_entitlements%ROWTYPE;
  v_collection_id UUID;
  v_card public.lottery_card_definitions%ROWTYPE;
  v_rarity public.lottery_card_rarity;
  v_roll INTEGER;
  v_count INTEGER;
  v_offset INTEGER;
  v_slot_index INTEGER;
  v_storage_slot INTEGER;
  v_cards JSONB := '[]'::JSONB;
BEGIN
  SELECT * INTO v_entitlement FROM public.kq_support_booster_entitlements
  WHERE id = p_entitlement_id AND user_id = p_user_id FOR UPDATE;
  IF NOT FOUND OR v_entitlement.status <> 'available' THEN RAISE EXCEPTION 'Support booster unavailable'; END IF;

  SELECT id INTO v_collection_id FROM public.lottery_card_collections
  WHERE code = 'BOTTE_DU_CHANVRIER_2026' AND is_active = TRUE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Support collection unavailable'; END IF;

  FOR v_slot_index IN 1..v_entitlement.card_count LOOP
    v_storage_slot := CASE WHEN v_entitlement.ticket_id IS NOT NULL THEN v_slot_index + 3 ELSE v_slot_index END;
    SELECT * INTO v_card FROM public.kq_pick_support_card(v_slot_index = 1);
    INSERT INTO public.lottery_card_instances(
      user_id, ticket_id, kq_support_entitlement_id, pack_slot, card_definition_id
    ) VALUES (p_user_id, v_entitlement.ticket_id, v_entitlement.id, v_storage_slot, v_card.id);
    v_cards := v_cards || jsonb_build_array(jsonb_build_object(
      'code', v_card.code, 'name', v_card.name, 'rarity', v_card.rarity,
      'packSlot', v_slot_index, 'imageUrl', v_card.image_url
    ));
  END LOOP;

  UPDATE public.kq_support_booster_entitlements SET status = 'opened', opened_at = now()
  WHERE id = v_entitlement.id;
  RETURN jsonb_build_object(
    'entitlementId', v_entitlement.id, 'cardCount', v_entitlement.card_count,
    'cards', v_cards, 'openedAt', now()
  );
END;
$$;


REVOKE ALL ON FUNCTION public.rpc_kq_open_support_booster(UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_kq_open_support_booster(UUID,UUID) TO service_role;

-- Preserve the deployed bot battle bookkeeping, only replacing its draw.
DO $$
DECLARE body TEXT; start_at INTEGER; end_at INTEGER;
  first_anchor TEXT:='    SELECT COUNT(*) INTO v_reward_count';
  last_anchor TEXT:='    OFFSET v_reward_offset LIMIT 1;';
BEGIN
  body:=pg_get_functiondef('public.rpc_kq_finalize_bot_battle(uuid,uuid,text,jsonb,integer,jsonb,text)'::REGPROCEDURE);
  start_at:=strpos(body,first_anchor); end_at:=strpos(body,last_anchor);
  IF start_at=0 OR end_at<=start_at THEN RAISE EXCEPTION 'kq_botte_bot_draw_patch_mismatch'; END IF;
  body:=overlay(body placing '    SELECT * INTO v_reward_card FROM public.kq_pick_support_card(false);'
    from start_at for end_at+length(last_anchor)-start_at);
  EXECUTE body;
END $$;

-- Verify the epic limit inside the same lock and transaction as consumption.
DO $$
DECLARE body TEXT; anchor TEXT:='  IF p_use_kind = ''support'' AND NOT (p_card_code = ANY(v_run.deck_codes)) THEN';
BEGIN
  body:=pg_get_functiondef('public.rpc_kq_play_support_card(uuid,uuid,text,smallint,text,timestamptz,jsonb)'::REGPROCEDURE);
  IF strpos(body,anchor)=0 THEN RAISE EXCEPTION 'kq_botte_card_play_patch_mismatch'; END IF;
  body:=replace(body,anchor,$guard$
  IF COALESCE((v_run.state->>'rulesVersion')::INTEGER,2)>=3 AND (
    NOT v_definition.is_active OR p_use_kind='pbi' OR p_card_code IN ('BOTTE-002', 'BOTTE-004', 'BOTTE-010', 'BOTTE-011', 'BOTTE-012', 'BOTTE-022', 'BOTTE-023', 'BOTTE-025')
  ) THEN RAISE EXCEPTION 'kq_support_card_archived'; END IF;
  IF COALESCE((v_run.state->>'rulesVersion')::INTEGER,2)>=3 AND EXISTS(
    SELECT 1 FROM public.kq_support_card_rules rule WHERE rule.card_definition_id=v_definition.id
      AND cardinality(rule.situation_codes)>0
      AND NOT(COALESCE(v_run.state->'situationCodes'->>p_stage_index,'')=ANY(rule.situation_codes))
  ) THEN RAISE EXCEPTION 'kq_support_situation_mismatch'; END IF;
  IF v_definition.rarity='epic' AND (
    EXISTS(SELECT 1 FROM public.kq_card_burn_receipts receipt JOIN public.lottery_card_definitions definition
      ON definition.id=receipt.card_definition_id WHERE receipt.run_id=p_run_id AND definition.rarity='epic')
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(COALESCE(v_run.state->'usedCards','[]'::JSONB)) used(code)
      JOIN public.lottery_card_definitions definition ON definition.code=used.code WHERE definition.rarity='epic')
  ) THEN RAISE EXCEPTION 'kq_epic_already_played'; END IF;
$guard$||anchor);
  EXECUTE body;
END $$;

-- Archived health items cannot be restored to boosters through editorial edits.
DO $$
DECLARE body TEXT; anchor TEXT:='  IF char_length(BTRIM(p_name)) < 3';
BEGIN
  body:=pg_get_functiondef('public.rpc_kq_update_botte_card_editorial(uuid,text,public.lottery_card_rarity,text,text,boolean,text,text)'::REGPROCEDURE);
  IF strpos(body,anchor)=0 THEN RAISE EXCEPTION 'kq_botte_editor_patch_mismatch'; END IF;
  body:=replace(body,anchor,$guard$
  IF EXISTS(SELECT 1 FROM public.lottery_card_definitions WHERE id=p_card_id
    AND public.kq_botte_official_rarity(code) IS NOT NULL
    AND p_rarity IS DISTINCT FROM public.kq_botte_official_rarity(code))
    THEN RAISE EXCEPTION 'kq_botte_rarity_locked'; END IF;
  IF p_is_active IS TRUE AND EXISTS(SELECT 1 FROM public.lottery_card_definitions
    WHERE id=p_card_id AND code IN ('BOTTE-002', 'BOTTE-004', 'BOTTE-010', 'BOTTE-011', 'BOTTE-012', 'BOTTE-022', 'BOTTE-023', 'BOTTE-025')) THEN RAISE EXCEPTION 'kq_support_card_archived'; END IF;
$guard$||anchor);
  EXECUTE body;
END $$;
COMMIT;
